        <div className="text-center pt-8 pb-4">
          <p className="text-text-muted text-xs">Kaique Finanças v1.0.0</p>
          <p className="text-zinc-700 text-[10px] mt-1">
            Feito com 💚 e Next.js
          </p>
        </div>
      </main>

      {/* MODAIS LOCAIS */}
      <EditProfileModal
        isOpen={isEditProfileOpen}
        onClose={() => setIsEditProfileOpen(false)}
