        message="ATENÇÃO: Todos os seus dados, cartões, extratos e metas serão apagados permanentemente. Esta ação não tem volta."
        confirmText="Excluir Conta"
        confirmColor="bg-rose-600 hover:bg-rose-700 text-text-main"
      />
    </div>
  );
}

